import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int numRows = nextInt();
        long[][] t = new long[numRows][];
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < numRows; i++) {
            t[i] = new long[i + 1];
            t[i][0] = t[i][i] = 1;
            for (int c = 1; c < i; c++) t[i][c] = t[i - 1][c - 1] + t[i - 1][c];
            if (i > 0) sb.append(',');
            sb.append('[');
            for (int c = 0; c <= i; c++) {
                if (c > 0) sb.append(',');
                sb.append(t[i][c]);
            }
            sb.append(']');
        }
        System.out.println(sb.append(']'));
    }
}

package main

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	numRows := nextInt()
	t := make([][]int, numRows)
	for i := range t {
		t[i] = make([]int, i+1)
		t[i][0], t[i][i] = 1, 1
		for c := 1; c < i; c++ {
			t[i][c] = t[i-1][c-1] + t[i-1][c]
		}
	}
	out, _ := json.Marshal(t)
	if numRows == 0 {
		out = []byte("[]") // a nil slice would marshal as null
	}
	fmt.Println(string(out))
}
